function pad(n){ return String(n).padStart(2,'0'); }
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const now = moscowIsoNow();
const stamp = moscowStamp();

// OPERATOR: edit query / request_text below before running. One query per run (v0.1).
return [{ json: {
  discovery_request_id: 'disc_'+stamp,
  created_at: now,
  requested_by: 'operator',
  request_text: 'найти конкурентов по займам под ПТС в Москве',
  query: 'займ под залог ПТС Москва',
  region: 'Москва',
  service_focus: 'pts_loan',
  requested_limit: 10,
  source_mode: 'apify_search',
  source_api: 'apify/google-search-scraper'
}}];

const r = $json;
const query = String(r.query || '').trim();
const limit = Math.min(10, parseInt(r.requested_limit) || 10);

// Apify Google Search Results Scraper input — minimal, low cost: one query, one page, organic only.
const apify_body = {
  queries: query,
  maxPagesPerQuery: 1,
  resultsPerPage: limit,
  countryCode: 'ru',
  languageCode: 'ru',
  includeUnfilteredResults: false,
  saveHtml: false,
  saveHtmlToKeyValueStore: false,
  geminiSearch: { enableGemini: false },
  perplexitySearch: { enablePerplexity: false, returnImages: false, returnRelatedQuestions: false },
  chatGptSearch: { enableChatGpt: false },
  copilotSearch: { enableCopilot: false },
  maximumLeadsEnrichmentRecords: 0
};

return [{ json: { ...r, apify_body } }];

const meta = $('Set Discovery Request').first().json;
const limit = Math.min(10, parseInt(meta.requested_limit) || 10);
function cap(s, n){ return (s == null ? '' : String(s)).substring(0, n); }

// Gather raw dataset items from whatever shape the HTTP node produced.
let datasetItems = [];
try {
  const all = $input.all().map(i => i.json);
  for (const it of all) {
    if (it == null) continue;
    if (Array.isArray(it)) datasetItems.push(...it);
    else datasetItems.push(it);
  }
} catch (e) { datasetItems = []; }

// Detect Apify error / empty response.
let ok = true; let errorPreview = '';
const first = datasetItems[0] || {};
if (datasetItems.length === 0) { ok = false; errorPreview = 'Empty Apify response (no dataset items).'; }
else if (first && (first.error || (first.statusCode && first.statusCode >= 400) || first.success === false)) {
  ok = false; errorPreview = cap('Apify error: ' + JSON.stringify(first.error || first.message || first.statusCode || first), 400);
}

// Collect organic-like results across dataset items.
function collectOrganic(di){
  const out = [];
  if (Array.isArray(di.organicResults)) out.push(...di.organicResults);
  if (Array.isArray(di.organic_results)) out.push(...di.organic_results);
  if (Array.isArray(di.results)) out.push(...di.results);
  if (out.length === 0 && (di.url || di.link)) out.push(di); // item is itself a result row
  return out;
}
let organic = [];
for (const di of datasetItems) { if (di && typeof di === 'object') organic.push(...collectOrganic(di)); }

// Drop Google-internal / non-website / login junk URLs.
function isJunk(u){
  const l = String(u || '').toLowerCase();
  if (!l) return true;
  if (!/^https?:\/\//.test(l)) return true;
  if (l.includes('google.') && (l.includes('/search') || l.includes('/url?') || l.includes('webcache') || l.includes('translate.google'))) return true;
  if (l.includes('googleusercontent') || l.includes('gstatic.com')) return true;
  if (l.includes('/maps') || l.startsWith('https://maps.')) return true;
  if (l.includes('accounts.google') || l.includes('/signin') || l.includes('/login')) return true;
  return false;
}

// URL normalizer — same rules as Workflow 04 (matches url_registry keys).
function normalizeUrl(u){
  u = String(u || '').trim();
  if (!u) return '';
  try {
    const noFrag = u.split('#')[0];
    const url = new URL(noFrag);
    url.protocol = (url.protocol || '').toLowerCase();
    url.hostname = (url.hostname || '').toLowerCase();
    const drop = ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','gclid','yclid','fbclid'];
    for (const p of drop) url.searchParams.delete(p);
    let path = url.pathname || '/';
    if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
    url.pathname = path;
    return url.toString();
  } catch (e) { return u; }
}

const seen = new Set();
const candidates = [];
let rank = 0;
for (const r of organic) {
  if (candidates.length >= limit) break;
  const rawUrl = String((r && (r.url || r.link)) || '').trim();
  if (!rawUrl || isJunk(rawUrl)) continue;
  if (seen.has(rawUrl)) continue; // drop exact raw duplicates within the batch
  seen.add(rawUrl);
  rank++;
  const norm = normalizeUrl(rawUrl);
  let domain = '';
  try { domain = new URL(norm).hostname; } catch (e) { domain = ''; }
  if (!domain) { const m = String(rawUrl).match(/^https?:\/\/([^\/?#]+)/i); domain = m ? m[1] : ''; }
  domain = domain.toLowerCase(); if (domain.indexOf('www.') === 0) domain = domain.slice(4);
  candidates.push({
    candidate_url: rawUrl,
    normalized_source_url: norm,
    title: cap(r.title || r.titleText || '', 300),
    snippet: cap(r.description || r.snippet || r.descriptionText || '', 600),
    domain: domain,
    rank: (r.position || r.rank || rank)
  });
}
if (ok && candidates.length === 0) { ok = false; errorPreview = errorPreview || 'Apify returned no usable organic results.'; }

return [{ json: {
  ok: ok && candidates.length > 0,
  error_preview: errorPreview,
  candidate_count_raw: candidates.length,
  candidates: candidates
}}];

const meta = $('Set Discovery Request').first().json;
const norm = $('Normalize Apify Results').first().json;
const candidates = Array.isArray(norm.candidates) ? norm.candidates : [];

// Read url_registry once (source of truth for dedup). Do NOT scan business tabs.
let registry = [];
try { registry = $('Read url_registry').all().map(i => i.json).filter(Boolean); } catch (e) { registry = []; }
const regSet = new Set(registry.map(r => String(r.normalized_source_url || '').trim()).filter(Boolean));

function pad(n){ return String(n).padStart(2,'0'); }
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const now = moscowIsoNow();
const stamp = moscowStamp();
function clamp(n){ return Math.min(100, Math.max(1, Math.round(n))); }

// Authoritative domain extraction (fix empty-domain bug): hostname, lowercase, strip leading www.
function extractDomain(u){
  let h = '';
  try { h = new URL(String(u||'').trim()).hostname; } catch (e) { h = ''; }
  if (!h) { const m = String(u||'').match(/^https?:\/\/([^\/?#]+)/i); h = m ? m[1] : ''; }
  h = h.toLowerCase();
  if (h.indexOf('www.') === 0) h = h.slice(4);
  return h;
}

function regionHint(l){
  if (l.includes('москва') || l.includes('московск') || l.includes('msk') || l.includes('moskva') || /(^|[^a-zа-я])мо([^a-zа-я]|$)/.test(l)) return 'Москва/МО';
  return '';
}
function serviceHint(l){
  if (l.includes('птс') || l.includes('pts') || l.includes('pod-zalog-pts') || l.includes('pledge-pts')) return 'pts_loan';
  if (l.includes('pod-zalog-avto') || l.includes('zalog-avto') || l.includes('автомобил') || l.includes('авто') || l.includes(' car ')) return 'secured_auto_loan';
  if (l.includes('недвиж') || l.includes('квартир') || l.includes(' дом') || l.includes('nedvizh') || l.includes('zemli') || l.includes('real estate')) return 'secured_real_estate_loan';
  if (l.includes('рефинанс') || l.includes('refinanc')) return 'refinancing';
  return 'unknown';
}
function looksLender(l){
  return l.includes('ломбард') || l.includes('lombard') || l.includes('autolombard') || l.includes('займ') || l.includes('заём') || l.includes('заим') || l.includes('кредит') || l.includes('финанс') || l.includes('finance') || l.includes('credit') || l.includes('loan');
}

// candidate_type classification (deterministic, no LLM).
const AGGREGATORS = ['banki.ru','vbr.ru','finuslugi.ru','sravni.ru','bankiros','myfin','vsezaimy','vse-zaimy','zaim.com','outbank','frbank','brobank'];
const DIRECTORIES = ['2gis.','zoon.','yell.ru','flamp.','orgpage','rusprofile','spr.ru','yandex.ru/maps','/maps'];
const MEDIA = ['kp.ru','rbc.ru','ria.ru','lenta.','vc.ru','dzen.ru','journal.tinkoff','pikabu','habr.','iz.ru','aif.ru','gazeta.ru'];
const MARKETPLACES = ['avito.','youla.','yula.','ozon.','wildberries','market.yandex','drom.ru','auto.ru'];
const SOCIALS = ['vk.com','ok.ru','instagram.','t.me','telegram','facebook.','youtube.','tiktok.','twitter.','x.com','dzen.ru/id'];
function candidateType(domain, base){
  const dl = domain.toLowerCase();
  if (SOCIALS.some(x => dl.includes(x))) return 'social';
  if (MARKETPLACES.some(x => dl.includes(x))) return 'marketplace';
  if (DIRECTORIES.some(x => dl.includes(x) || base.includes(x))) return 'directory';
  if (AGGREGATORS.some(x => dl.includes(x))) return 'aggregator';
  if (MEDIA.some(x => dl.includes(x))) return 'media_article';
  if (/\/(news|article|articles|blog|stati|statya|reviews|rating|reyting|top-?\d|luchshi|obzor)(\/|$)/.test(base)) return 'media_article';
  if (looksLender(base) || dl.includes('lombard') || dl.includes('zalog') || dl.includes('credit') || dl.includes('cash') || dl.includes('finans') || dl.includes('zaim') || dl.includes('lombard')) return 'direct_competitor';
  return 'unknown';
}

const query = String(meta.query || '').toLowerCase();
const wantsMarket = /авито|маркетплейс|объявлен|avito|youla|юла/.test(query);

const batchSeen = new Set();
const rows = [];
let unique = 0, dups = 0, estFc = 0, estClaude = 0;

for (let i = 0; i < candidates.length; i++) {
  const c = candidates[i];
  const key = String(c.normalized_source_url || '').trim();
  const domain = extractDomain(c.normalized_source_url || c.candidate_url);
  // base = candidate text only (for confidence); hay = base + query (for intent-aware hints).
  const base = ((c.title||'') + ' ' + (c.snippet||'') + ' ' + domain + ' ' + (c.candidate_url||'')).toLowerCase();
  const hay = base + ' ' + query;

  const inRegistry = key !== '' && regSet.has(key);
  let dedup_status = 'unique';
  if (inRegistry) dedup_status = 'duplicate_in_registry';
  else if (key !== '' && batchSeen.has(key)) dedup_status = 'duplicate_in_batch';
  if (!inRegistry && key !== '') batchSeen.add(key);

  const registry_status = inRegistry ? 'in_registry' : 'not_in_registry';
  const isDup = (dedup_status !== 'unique');
  const approval_status = isDup ? 'duplicate' : 'new';

  const candidate_type = candidateType(domain, base);

  // Confidence: direct competitors rank above aggregators/directories/media.
  let s = 10;
  if (candidate_type === 'direct_competitor') s += 30;
  if (base.includes('залог')) s += 20;
  if (base.includes('птс') || base.includes('pts')) s += 20;
  if (base.includes('авто') || base.includes('автомобил')) s += 15;
  if (base.includes('москва') || base.includes('московск') || base.includes('msk') || base.includes('moskva')) s += 15;
  if (base.includes('кредит') || base.includes('займ') || base.includes('заём')) s += 10;
  if (base.includes('ставка') || base.includes('сумма') || base.includes('одобрен')) s += 10;
  if (looksLender(base)) s += 10;
  if (dedup_status === 'duplicate_in_registry') s -= 50;
  if (candidate_type === 'directory') s -= 35;
  if (candidate_type === 'aggregator') s -= 25;
  if (candidate_type === 'media_article') s -= 20;
  if (candidate_type === 'marketplace' && !wantsMarket) s -= 20;
  if (candidate_type === 'social') s -= 30;
  const confidence_score = clamp(s);

  const est_fc = (approval_status === 'new') ? 1 : 0;
  const est_cl = (approval_status === 'new') ? 0.02 : 0;
  if (approval_status === 'new') { unique++; estFc += est_fc; estClaude += est_cl; } else { dups++; }

  let note;
  if (isDup) {
    note = 'Duplicate; do not process unless force_reprocess later. Requires human approval before Workflow 04.';
  } else if (candidate_type !== 'direct_competitor') {
    note = 'Review manually; not a direct competitor (' + candidate_type + '). Requires human approval before Workflow 04.';
  } else {
    note = 'Requires human approval before Workflow 04.';
  }

  rows.push({
    candidate_id: 'cand_' + stamp + '_' + (i + 1),
    discovery_request_id: meta.discovery_request_id,
    created_at: now,
    requested_by: meta.requested_by || 'operator',
    requested_limit: meta.requested_limit || 10,
    query: meta.query || '',
    source: 'apify_search',
    candidate_url: c.candidate_url || '',
    normalized_source_url: key,
    domain: domain,
    candidate_type: candidate_type,
    title: c.title || '',
    snippet: c.snippet || '',
    rank: c.rank || (i + 1),
    region_hint: regionHint(hay),
    service_hint: serviceHint(hay),
    confidence_score: confidence_score,
    dedup_status: dedup_status,
    registry_status: registry_status,
    approval_status: approval_status,
    approved_by: '',
    approved_at: '',
    rejection_reason: '',
    estimated_firecrawl_credits: est_fc,
    estimated_claude_cost_usd: est_cl,
    notes: note
  });
}

return [{ json: {
  meta: meta,
  ok: (norm.ok === true) && rows.length > 0,
  error_preview: norm.error_preview || '',
  candidateRows: rows,
  candidate_count: rows.length,
  unique_candidate_count: unique,
  duplicate_count: dups,
  estimated_firecrawl_credits: estFc,
  estimated_claude_cost_usd: Math.round(estClaude * 1000) / 1000
}}];

const c = $json;
const rows = Array.isArray(c.candidateRows) ? c.candidateRows : [];
// Fan out 0..10 candidate rows for Append url_candidates. 0 → nothing appended.
return rows.map(r => ({ json: r }));

const c = $('Classify Candidates').first().json;
const meta = c.meta || $('Set Discovery Request').first().json;
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
const now = moscowIsoNow();
const count = c.candidate_count || 0;
const status = (c.ok === true && count > 0) ? 'needs_review' : 'error';

let notes = (status === 'needs_review')
  ? ('Discovery via Apify Google Search. ' + count + ' candidates (' + (c.unique_candidate_count||0) + ' new, ' + (c.duplicate_count||0) + ' duplicate). Requires human approval before Workflow 04.')
  : ('Apify discovery returned no usable candidates. ' + (c.error_preview || ''));
notes = String(notes).substring(0, 500);

return [{ json: {
  discovery_request_id: meta.discovery_request_id,
  created_at: meta.created_at || now,
  requested_by: meta.requested_by || 'operator',
  request_text: meta.request_text || '',
  query: meta.query || '',
  region: meta.region || '',
  service_focus: meta.service_focus || '',
  requested_limit: meta.requested_limit || 10,
  source_mode: 'apify_search',
  source_api: 'apify/google-search-scraper',
  status: status,
  candidate_count: count,
  unique_candidate_count: c.unique_candidate_count || 0,
  duplicate_count: c.duplicate_count || 0,
  approved_count: 0,
  estimated_firecrawl_credits: c.estimated_firecrawl_credits || 0,
  estimated_claude_cost_usd: c.estimated_claude_cost_usd || 0,
  notes: notes
}}];

function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
// WF05 live_source_runs ledger (23 cols, DEC-126). Apify search discovery run. No new external calls here.
function str(v){return v==null?'':String(v).trim();}
const s=$('Build Discovery Request Summary').first().json;
const cfg=$('Set Discovery Request').first().json||{};
const cnt=Number(s.candidate_count)||0;
const st=(str(s.status)==='needs_review')?'completed':(cnt>0?'partial':'failed');
return [{ json: {
  run_id:str(s.discovery_request_id)||('disc_'+Date.now()),
  created_at:moscowIsoNow(),
  workflow:'WF05 - Apify Search Candidate Discovery',
  source_family:'web_competitor',
  platform:'apify_search',
  mode:'live',
  approval_token_used:'no',
  source_allowlist:str(s.query||cfg.query),
  max_items:Number(s.requested_limit)||Number(cfg.requested_limit)||10,
  items_received:cnt,
  items_relevant:cnt,
  items_written_raw:0,
  items_unique:Number(s.unique_candidate_count)||0,
  items_duplicate:Number(s.duplicate_count)||0,
  hard_skipped:0,
  external_calls:1,
  estimated_source_cost_usd:0,
  llm_calls:0,
  estimated_llm_cost_usd:0,
  status:st,
  error_summary:(st==='failed'?str(s.notes):''),
  operator_next_action:'Approve direct_competitor candidates in url_candidates, then run WF06.',
  notes:'Apify google-search discovery; cost not recovered (apify_search). Writes url_candidates (not raw_market_records).'
}}];
